import React from 'react';
import data from './../data/experienceData.js';
import { FaBriefcase, FaMapMarkerAlt, FaCalendarAlt, FaCode } from 'react-icons/fa';

function Experience() {
  return (
    <section id="experience" className='py-20 px-6 sm:px-8 lg:px-12 relative overflow-hidden'>
      {/* Simple Background */}
      <div className="absolute inset-0 bg-gradient-to-br from-[#0F1419] via-[#1A1D23] to-[#0F1419]"></div>

      <div className="max-w-6xl mx-auto relative z-10">
        {/* Simple Section Header */}
        <div className="text-center mb-16 animate-fade-in-up">
          <h2 className="text-3xl sm:text-4xl md:text-5xl font-bold text-white mb-6">
            Experience
          </h2>
          <div className="w-24 h-1 bg-[#3B82F6] mx-auto rounded-full"></div>
        </div>

        {/* Simple Grid Layout */}
        <div className="space-y-8">
          {data.map((exp, index) => (
            <SimpleExperienceCard key={exp.id} experience={exp} index={index} />
          ))}
        </div>
      </div>
    </section>
  );
}

// Simple, Clean Experience Card
function SimpleExperienceCard({ experience, index }) {
  return (
    <div className="glass-effect-strong rounded-2xl p-8 hover:shadow-glow transition-all duration-300 animate-fade-in-up" 
         style={{ animationDelay: `${index * 0.1}s` }}>

      {/* Header Section */}
      <div className="flex flex-col md:flex-row md:items-start md:justify-between mb-6">
        <div className="mb-4 md:mb-0">
          <h3 className="text-2xl font-bold text-white mb-2">{experience.title}</h3>
          <div className="flex items-center gap-2 mb-2">
            <FaBriefcase className="text-[#3B82F6] text-sm" />
            <span className="text-[#3B82F6] font-semibold text-lg">{experience.org}</span>
          </div>
        </div>

        <div className="flex flex-col md:items-end space-y-2">
          <div className="flex items-center gap-2 text-gray-400">
            <FaCalendarAlt className="text-[#3B82F6]" />
            <span>{experience.date}</span>
          </div>
          <div className="flex items-center gap-2 text-gray-400">
            <FaMapMarkerAlt className="text-[#3B82F6]" />
            <span>{experience.location}</span>
          </div>
          <span className={`px-3 py-1 rounded-full text-sm font-medium ${
            experience.type === 'Full-time' ? 'bg-green-500/20 text-green-400' :
            experience.type === 'Internship' ? 'bg-[#3B82F6]/20 text-[#3B82F6]' :
            'bg-purple-500/20 text-purple-400'
          }`}>
            {experience.type}
          </span>
        </div>
      </div>

      {/* Description */}
      <p className="text-gray-300 text-base leading-relaxed mb-6">
        {experience.description}
      </p>

      {/* Responsibilities & Achievements in Two Columns */}
      <div className="grid grid-cols-1 lg:grid-cols-2 gap-8 mb-6">
        {/* Responsibilities */}
        <div>
          <h4 className="text-white font-semibold mb-3">Key Responsibilities</h4>
          <ul className="space-y-2">
            {experience.responsibilities.map((resp, idx) => (
              <li key={idx} className="flex items-start gap-3">
                <div className="w-1.5 h-1.5 bg-[#3B82F6] rounded-full mt-2 flex-shrink-0"></div>
                <span className="text-gray-300 text-sm">{resp}</span>
              </li>
            ))}
          </ul>
        </div>

        {/* Achievements */}
        <div>
          <h4 className="text-white font-semibold mb-3">Key Achievements</h4>
          <ul className="space-y-2">
            {experience.achievements.map((achievement, idx) => (
              <li key={idx} className="flex items-start gap-3">
                <div className="w-1.5 h-1.5 bg-[#60A5FA] rounded-full mt-2 flex-shrink-0"></div>
                <span className="text-gray-300 text-sm">{achievement}</span>
              </li>
            ))}
          </ul>
        </div>
      </div>

      {/* Technologies */}
      <div>
        <h4 className="text-white font-semibold mb-3 flex items-center gap-2">
          <FaCode className="text-[#3B82F6]" />
          Technologies
        </h4>
        <div className="flex flex-wrap gap-2">
          {experience.technologies.map((tech, idx) => (
            <span 
              key={idx} 
              className="px-3 py-1 bg-[#3B82F6]/10 text-[#3B82F6] rounded-lg text-sm border border-[#3B82F6]/20 hover:bg-[#3B82F6]/20 transition-colors duration-300"
            >
              {tech}
            </span>
          ))}
        </div>
      </div>
    </div>
  );
}

export default Experience;
